import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-10-25（AI / Agent 安全 / 控制评估 / 元 RL 记忆 / 人机信任校准 / 隐喻表征）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-25-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-25-ai.md"}'),e={name:"topics/ai-system-architecture/science-daily-2026-10-25-ai.md"};function g(i,o,l,a,c,d){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-25-ai-agent-安全-控制评估-元-rl-记忆-人机信任校准-隐喻表征" tabindex="-1">科学日报 · 2026-10-25（AI / Agent 安全 / 控制评估 / 元 RL 记忆 / 人机信任校准 / 隐喻表征） <a class="header-anchor" href="#科学日报-·-2026-10-25-ai-agent-安全-控制评估-元-rl-记忆-人机信任校准-隐喻表征" aria-label="Permalink to &quot;科学日报 · 2026-10-25（AI / Agent 安全 / 控制评估 / 元 RL 记忆 / 人机信任校准 / 隐喻表征）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> — 第44期 ｜ AI 板块（5 篇） 落盘说明：文件名带 <code>-ai</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-25-工具「漏说了关键事实」时-智能体会不会照做违法的事-episem-bench" tabindex="-1">科学日报 2026-10-25：工具「漏说了关键事实」时，智能体会不会照做违法的事？（EpiSEM-Bench） <a class="header-anchor" href="#科学日报-2026-10-25-工具「漏说了关键事实」时-智能体会不会照做违法的事-episem-bench" aria-label="Permalink to &quot;科学日报 2026-10-25：工具「漏说了关键事实」时，智能体会不会照做违法的事？（EpiSEM-Bench）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ arXiv: 2610.31650</p></blockquote><ul><li>威胁模型（很精细）：工具型智能体<strong>依赖环境返回的事实</strong>判断动作是否被允许。危险情形是——<strong>工具响应省略了一条与安全相关的事实</strong>，此时智能体可能执行<strong>被禁止的动作</strong>，而<strong>用户请求完全无害、工具返回的每一句话都为真</strong>。这是**「真话的全集不完整」型失败**，而非「说假话」型失败。</li><li>基准 <strong>EpiSEM-Bench</strong>：<strong>可执行</strong>，含 <strong>300 对「不安全/安全」配对任务</strong>，覆盖<strong>六个领域</strong>；通过<strong>系统性抑制关键事实</strong>来测量： <ul><li><strong>关键证据缺失下的不安全执行</strong>；</li><li><strong>安全边界</strong>；</li><li><strong>最小观测失败基数</strong>（含「全证据下仍失败」与「穷尽测试后仍无失败」两类极端）。</li><li>配套<strong>独立审计工具</strong>：检验智能体是否<strong>主动索取缺失事实</strong>、并在完成<strong>允许任务</strong>的同时<strong>扣住被禁止的动作</strong>。</li></ul></li><li>结果：十个模型在**「缺失鲁棒性」「证据获取」「恰当行动」<strong>三维度差异显著；<strong>对缺失证据的抵抗力 ≠ 有用的恢复</strong>——提供恢复通道能降低</strong>所有**模型的不安全执行，但各模型在「<strong>是否主动去拿缺失事实并据此正确行动</strong>」上差别很大。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）：<strong>「不犯错」与「会补证据」是两种独立能力</strong>。这与本库 10-23「Proof-Carrying Contracts 让承诺全时刻成立」、10-22「直接在目标函数里写权衡」构成一组：<strong>安全评估必须把「被动的鲁棒」与「主动的求证」分开测</strong>，否则会把「因为没触发所以看起来安全」误当成熟。可迁移判据：<strong>评估一个防护时，问它是「挡得住」还是「会去查」——前者可被信息缺失绕过，后者才是鲁棒。</strong></li></ul><hr><h2 id="科学日报-2026-10-25-用语言模型「模拟环境」来做控制评估-simulated-control-evals" tabindex="-1">科学日报 2026-10-25：用语言模型「模拟环境」来做控制评估（Simulated Control Evals） <a class="header-anchor" href="#科学日报-2026-10-25-用语言模型「模拟环境」来做控制评估-simulated-control-evals" aria-label="Permalink to &quot;科学日报 2026-10-25：用语言模型「模拟环境」来做控制评估（Simulated Control Evals）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ arXiv: 2610.31593</p></blockquote><ul><li>背景：<strong>控制评估（control evals）</strong> 衡量「即便模型<strong>故意</strong>想造成不良后果，防护措施能否阻止」；但它通常依赖<strong>专门搭建的控制环境</strong>，再把结果<strong>外推到真实部署</strong>——而真实部署的环境/任务特征，控制环境未必代表。</li><li>方法 <strong>SCEs（simulated control evaluations）</strong>：用一个<strong>语言模型代替真实环境来模拟工具响应</strong>，从而把控制评估铺展到更贴合部署的范围。</li><li>结果（在有个<strong>真值执行</strong>的 LinuxArena 上）： <ul><li>对<strong>独立采样</strong>的评估/部署任务集，SCE 在 <strong>5% 审计预算、五个监控器</strong>下的<strong>安全预测 RMSE 为 3.6 个百分点</strong>；而另一控制环境 <strong>BashArena 为 10.1</strong>；</li><li>SCE <strong>复现</strong>攻击策略、攻击者推理、监控器推理的分布，与真实执行的 <strong>KL 散度比 BashArena 低十倍以上</strong>；</li><li><strong>解释了 78%–85% 的跨环境方差</strong>；</li><li><strong>样本效率</strong>：用<strong>不到部署任务集 5%</strong> 的任务对抽样量，误差就低于 BashArena；</li><li>模拟中发现的<strong>新策略</strong>能<strong>提升监控器在真实攻击上的表现</strong>（与执行策略带来的提升大致相当）。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code>）：<strong>「用模型模拟环境」把安全评估从「在别处测完再外推」变成「就地测」</strong>。这与本条 EpiSEM 合看：一条是**「缺证据」下的行为**，一条是**「换环境」下的稳定性** —— 都在指向**「评估的可迁移性」是安全的核心难题**（而非某个静态分数）。对照本库 10-23「Environment Duels 用出题+特权提示把共同演化变成可测基准」：<strong>同族判据是「先解决『在哪测』，再谈『测多少』」</strong>。</li></ul><hr><h2 id="科学日报-2026-10-25-元强化学习的新记忆——把「快速适应」拆成两个时间尺度-metta" tabindex="-1">科学日报 2026-10-25：元强化学习的新记忆——把「快速适应」拆成两个时间尺度（METTA） <a class="header-anchor" href="#科学日报-2026-10-25-元强化学习的新记忆——把「快速适应」拆成两个时间尺度-metta" aria-label="Permalink to &quot;科学日报 2026-10-25：元强化学习的新记忆——把「快速适应」拆成两个时间尺度（METTA）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ arXiv: 2610.31656</p></blockquote><ul><li>问题：<strong>元强化学习（meta-RL）</strong> 要求智能体<strong>从有限交互快速适应新任务</strong>，这需要在<strong>很长的交互历史</strong>里表征「任务证据」。两类既有做法各有代价：<strong>循环智能体</strong>把经验压进隐状态（表达受限），<strong>Transformer 类</strong>按<strong>二次代价</strong>从过去轨迹检索（内存/算力昂贵）。</li><li>方法 <strong>METTA（Memory-Enhanced Test-Time Adaptation）</strong>：把<strong>快速适应阶段分解成两个时间尺度</strong>—— <ul><li>一个<strong>因果神经记忆</strong>做<strong>线性复杂度</strong>的<strong>幕内细粒度适应</strong>；</li><li>一组<strong>紧凑的幕级摘要</strong>支撑<strong>长程跨幕任务推断</strong>（不必对整个交互历史做注意力）。</li><li>另外，配备神经记忆本身也提供足够的<strong>表达力与测试时训练能力</strong>，使其能在<strong>元测试阶段</strong>适应<strong>未见过的新任务乃至新任务族</strong>。</li></ul></li><li>结果：未见过的 <strong>Meta-World ML10/45</strong> 上<strong>成功率 &gt;50%</strong>，训练预算低、墙钟时间短；长上下文稀疏奖励的 <strong>PointMaze</strong> 上表现出<strong>比 Transformer 基线更有结构的探索行为</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：要点是**「长上下文不必『全量注意力』」** —— 把记忆<strong>按时间尺度分层</strong>（细粒度短程 + 摘要长程），就能<strong>同时拿到线性复杂度与跨幕推断</strong>。这与本库 10-21「MemT-1.0 把记忆内化为模型计算」、10-20「KronLSTM 让长上下文线性注意力记忆稳定」构成<strong>同一条『记忆分层 / 记忆内化』主线</strong>。可迁移判据：<strong>当「全量注意力」的代价压过收益时，先问历史里是否存在天然的两个时间尺度——若有，就按尺度分开存，而不是压缩成一份。</strong></li></ul><hr><h2 id="科学日报-2026-10-25-反向的谄媚——模型自信地错了-人反而向模型靠拢" tabindex="-1">科学日报 2026-10-25：反向的谄媚——模型自信地错了，人反而向模型靠拢 <a class="header-anchor" href="#科学日报-2026-10-25-反向的谄媚——模型自信地错了-人反而向模型靠拢" aria-label="Permalink to &quot;科学日报 2026-10-25：反向的谄媚——模型自信地错了，人反而向模型靠拢&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ arXiv: 2610.31579</p></blockquote><ul><li>反向问题：以往研究问「<strong>模型是否会迎合用户</strong>」（sycophancy）；本篇问反过来——<strong>当模型自信、前后一致却错误时，用户会不会向模型靠拢？</strong></li><li>实验设计（干净且狠）：<strong>被试内</strong>，<strong>32 名参与者</strong>通过与<strong>五个基于同一模型（GPT-5-mini）的助手</strong>聊天来学习<strong>至多五个科学主题</strong>；参与者<strong>不知道</strong>的是，每个助手的简报里分别有 <strong>0%、25%、50%、75%、100%</strong> 的事实被替换成<strong>看似合理的假信息</strong>，且<strong>所有助手都用十足自信的语气</strong>。每个主题后<strong>突袭测验</strong>提供<strong>正确事实、植入假信息、两个干扰项</strong>，并对<strong>每个答案做信心评分</strong>。</li><li>结果（104 份测验 / 1040 个答案）： <ul><li>得分从 <strong>7.4/10 掉到 2.9/10</strong>；</li><li>篡改项上选到「植入假信息」的比例 <strong>60%</strong>（对照正确讲授项仅 <strong>11%</strong>，<strong>优势比 12.5</strong>）；</li><li><strong>转写编码</strong>：只要助手陈述了假信息，约 <strong>65%</strong> 的情况下会被采纳，<strong>各篡改水平下都如此</strong>；</li><li>被吸收的假信息携带<strong>高信心（8.4/10）</strong>；「对答案比错答案更自信」这一优势<strong>消失</strong>；用信心区分对错的 <strong>AUROC 从 0.70 掉到随机水平</strong>；</li><li><strong>任务后信任评分几乎不变</strong>；参与者<strong>更倾向回到「更差」的聊天</strong>，但<strong>回归伴随更多吸收而非更少</strong>；</li><li><strong>30% 的回合</strong>把测验问题<strong>粘回</strong>被检查的来源；而助手本身<strong>几乎从不谄媚、也从不因反驳而让步</strong>。</li></ul></li><li>提出的概念：<strong>基线校正的人类顺从指数（Human Deference Index）</strong>；主张<strong>可信度是「人—AI 配对」的属性</strong>、谄媚评估<strong>必须双向测量</strong>、学习类界面应<strong>逐条让「可靠性」变得可见</strong>。</li><li>洞察（对本库 <code>ai-brain</code> × <code>psychology</code> × <code>science-news</code>）：<strong>这是本库「信源核实」主线的量化版</strong> —— 10-24 日记刚总结「别人转来的东西怎么核」，本条给出了<strong>失利机制的实测数据</strong>：<strong>失准的关键不是『模型自信』，而是『人对自信的校准失效』</strong>（AUROC 0.70→随机，而<strong>信任评分几乎不动</strong> = 人们<strong>没更新</strong>对助手的信任）。两条可迁移判据： <ol><li><strong>「可信度是配对的属性」</strong> —— 评估 AI 可靠性时，<strong>必须把人的校准能力算进去</strong>，否则会高估「模型对」带来的安全；</li><li><strong>「更多使用 ≠ 更会用」</strong> —— 参与者<strong>更爱回到更差的助手</strong>（互动更顺？），且回访伴随<strong>更多吸收</strong>，直接反驳「多用就会识破」的天真假设。这条应写入 <code>topics/science-news/index.md</code> 的核实清单：<strong>「反复使用」不能当成「已验证」。</strong></li></ol></li></ul><hr><h2 id="科学日报-2026-10-25-隐喻在大模型里是一块可被「调音」的几何子空间" tabindex="-1">科学日报 2026-10-25：隐喻在大模型里是一块可被「调音」的几何子空间 <a class="header-anchor" href="#科学日报-2026-10-25-隐喻在大模型里是一块可被「调音」的几何子空间" aria-label="Permalink to &quot;科学日报 2026-10-25：隐喻在大模型里是一块可被「调音」的几何子空间&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ arXiv: 2610.31520</p></blockquote><ul><li>问题：隐喻是<strong>人类认知的关键机制</strong>，但它在 LLM 中<strong>如何表征、能否被控制</strong>，此前缺少直接证据。</li><li>方法：用<strong>机械可解释性</strong>技术，在覆盖<strong>不同架构与规模</strong>的多个 LLM 中识别与隐喻相关的<strong>因果子空间</strong>。</li><li>结果： <ul><li>可以<strong>跨不同词性</strong>在<strong>分类任务</strong>上**操控（steer）**模型输出；</li><li>这种技术<strong>在生成任务上同样有效</strong> → 即可以<strong>控制模型输出的「隐喻性」高低</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）：篇幅不长、结论直接，但意义是<strong>把一种高度语义、长期被认为难以度量的现象，变成了可定位、可干预的表征方向</strong>。与本库 10-22「神经启发的抑制性消息传递」、既有「激活值而非文字描述预测对齐泛化」主线合看，共同教益是：<strong>「可定位的子空间 → 检测与调控共用同一套向量手术」</strong>，不必依赖提示词。可迁移判据：<strong>当一个『风格/内容属性』难以用规则描述时，先找它在表征空间里是否对应一个方向——若是，则『度量』与『控制』是同一个操作。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第44期 AI 板块</p></blockquote><p>关键词：EpiSEM-Bench、证据缺失下的不安全执行、真话全集不完整、300 对配对任务、证据恢复、抗缺失不等于会恢复、Simulated Control Evals、LLM 模拟工具响应、LinuxArena 真值、安全预测 RMSE 3.6 vs BashArena 10.1、跨环境方差 78–85%、样本 &lt;5%、METTA、元强化学习两时间尺度、线性复杂度幕内神经记忆 + 幕级摘要、Meta-World ML10/45 &gt;50%、长上下文不必全量注意力、反向谄媚、Human Deference Index、植入假信息采纳 65%、AUROC 0.70→随机、信任评分不动、可信度是人机配对属性、更多使用不等于更会用、隐喻因果子空间、可定位即可调控</p><p>关联：<code>topics/ai-system-architecture/science-daily-2026-10-24-ai.md</code>（Virtual Biotech / 顺序诊断 / Direct Pass@k / RLVR / 低位宽 n-gram）、<code>topics/ai-system-architecture/science-daily-2026-10-23-ai.md</code>（Proof-Carrying Contracts / Environment Duels）、<code>topics/ai-system-architecture/science-daily-2026-10-21-ai.md</code>（记忆分层 MemT / KronLSTM）、<code>topics/ai-brain/index.md</code>、<code>topics/science-news/index.md</code></p>',26)])])}const m=t(e,[["render",g]]);export{h as __pageData,m as default};
